/**
 * Bundle db/migrations/*.sql into a TypeScript module the app can import.
 *
 * React Native / Metro can't import raw .sql, so the .sql files (the canonical,
 * node:sqlite-validated source of truth) are inlined into
 * src/lib/db/migrations.generated.ts as a typed array. Run this after adding or
 * editing any migration:  npm run db:bundle  (and commit the generated file,
 * like a lockfile). `npm run db:validate` checks the generated copy is in sync.
 *
 * Usage: node db/bundle-migrations.mjs [--check]
 *   --check  exit non-zero if the generated file is stale (for CI / db:validate)
 */
import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const root = dirname(fileURLToPath(import.meta.url));
const migrationsDir = join(root, 'migrations');
const outFile = join(root, '..', 'src', 'lib', 'db', 'migrations.generated.ts');
const check = process.argv.includes('--check');

const files = readdirSync(migrationsDir)
  .filter((f) => /^\d+_.+\.sql$/.test(f))
  .sort();

if (files.length === 0) {
  console.error('No migrations found in db/migrations (expected NNNN_name.sql).');
  process.exit(1);
}

const migrations = files.map((f) => ({
  version: parseInt(/^(\d+)/.exec(f)[1], 10),
  name: f.replace(/\.sql$/, ''),
  sql: readFileSync(join(migrationsDir, f), 'utf8'),
}));

// Enforce strictly-increasing, unique versions here so a bad filename fails at
// build time, not on the user's phone.
migrations.forEach((m, i) => {
  if (m.version < 1) throw new Error(`Migration ${m.name} has version < 1.`);
  if (i > 0 && migrations[i - 1].version >= m.version) {
    throw new Error(`Migrations out of order or duplicated at ${m.name} (v${m.version}).`);
  }
});

const banner = `// GENERATED by db/bundle-migrations.mjs — do not edit by hand.
// Run \`npm run db:bundle\` after changing any db/migrations/*.sql, and commit this file.
`;
const body = `import type { Migration } from './migrate';

export const MIGRATIONS: Migration[] = ${JSON.stringify(migrations, null, 2)};
`;
const contents = banner + '\n' + body;

if (check) {
  let current = '';
  try {
    current = readFileSync(outFile, 'utf8');
  } catch {
    /* missing counts as stale */
  }
  if (current !== contents) {
    console.error('migrations.generated.ts is stale — run `npm run db:bundle` and commit.');
    process.exit(1);
  }
  console.log(`migrations.generated.ts is in sync (${migrations.length} migration(s)).`);
} else {
  writeFileSync(outFile, contents);
  console.log(`Wrote ${migrations.length} migration(s) to src/lib/db/migrations.generated.ts`);
}
